    TwistSquash::SquashKeyA(REGULUS_KEY_A_D_IceLaneA, REGULUS_KEY_A_D_IceLaneB, REGULUS_KEY_A_D_IceLaneC, REGULUS_KEY_A_D_IceLaneD, &(pWorkSpace->mKeyBoxA[3U][0]));

